1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Customer = {
14	  yearsWithMHPCO: number;
15	};
16	
17	export type Damage = {
18	  itemType: string;
19	  amount: number;
20	};
21	
22	export type Incident = {
23	  cause: string;
24	  damages: Damage[];
25	};
26	
27	export type ClaimStep = {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	};
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type ScenarioResult = {
41	  results: unknown[];
42	};
43	
44	const PROCESSING_FEE = 5;
45	
46	// Only the main item types. Components are priced separately: individually,
47	// or as a discounted block of 3 alike ones.
48	const BASE_PREMIUMS: Record<string, number> = {
49	  sword: 100,
50	  amulet: 60,
51	  staff: 80,
52	  potion: 40,
53	};
54	
55	// Insurance values are the SUM INSURED per item - distinct from the base
56	// premiums above, which price the policy.
57	const INSURANCE_VALUES: Record<string, number> = {
58	  sword: 1000,
59	  amulet: 600,
60	  staff: 800,
61	  potion: 400,
62	};
63	
64	const COMPONENT_INSURANCE_VALUE = 250;
65	const DEDUCTIBLE_PER_DAMAGE = 100;
66	
67	// A CLAIM-side rule, unrelated to the premium-side
68	// ENCHANTMENT_SURCHARGE_THRESHOLD of 5; the two merely both key off
69	// enchantment, and are deliberately kept as separate numbers.
70	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
71	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
72	const CAP_MULTIPLE = 2;
73	
74	// Derived from the premium table rather than listed again, so the set of
75	// underwritten main types cannot drift from the set that can be priced.
76	const MAIN_ITEM_TYPES = Object.keys(BASE_PREMIUMS);
77	
78	const COMPONENT_TYPES = ["rune", "moonstone"];
79	const COMPONENT_BASE_PREMIUM = 25;
80	const BLOCK_SIZE = 3;
81	const BLOCK_BASE_PREMIUM = 60;
82	
83	const isComponent = (item: Item): boolean =>
84	  COMPONENT_TYPES.includes(item.type);
85	
86	// Modifiers are additive percentages of the UNMODIFIED base premium, never
87	// compounding multipliers, and are kept as exact fractions rather than float
88	// multipliers: 100 * 1.1 is 110.00000000000001 in IEEE-754. Only the final
89	// premium is rounded, so intermediate amounts stay fractional.
90	const percentOf = (amount: number, percent: number): number =>
91	  (amount * percent) / 100;
92	
93	// Modifiers are signed terms in one additive sum, so a discount is simply a
94	// negative percentage. Naming the sign keeps it from riding on a single easily
95	// overlooked "-" at a call site.
96	const discountOf = (amount: number, percent: number): number =>
97	  -percentOf(amount, percent);
98	
99	const FIRST_INSURANCE_PERCENT = 10;
100	const CURSE_PERCENT = 50;
101	const HIGH_ENCHANTMENT_PERCENT = 30;
102	const ENCHANTMENT_SURCHARGE_THRESHOLD = 5;
103	const LOYALTY_DISCOUNT_PERCENT = 20;
104	const LOYALTY_THRESHOLD_YEARS = 2;
105	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
106	
107	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
108	
109	// A group of exactly 3 alike components is offered at a block price. Any
110	// other count is priced per component.
111	const componentGroupPremium = (count: number): number =>
112	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
113	
114	// Components are priced per group of alike ones, so each distinct type is
115	// counted and priced on its own.
116	const componentsPremium = (components: Item[]): number => {
117	  const distinctTypes = new Set(components.map((component) => component.type));
118	
119	  return [...distinctTypes].reduce((sum, type) => {
120	    const alike = components.filter((component) => component.type === type);
121	    return sum + componentGroupPremium(alike.length);
122	  }, 0);
123	};
124	
125	// Splits a quote's items into the two independently-priced kinds, so the
126	// main/component distinction is decided in exactly one place.
127	const partitionByComponent = (
128	  items: Item[],
129	): { mainItems: Item[]; components: Item[] } => ({
130	  mainItems: items.filter((item) => !isComponent(item)),
131	  components: items.filter(isComponent),
132	});
133	
134	// Item-specific modifiers apply to the affected item's OWN base premium, not
135	// to the policy total. They are independent: a cursed, highly enchanted item
136	// carries both, so each item sums the surcharges that apply to it.
137	// Named for the consequence rather than the measurement, so it cannot be
138	// mistaken for the claim-side qualifiesForHalfReimbursement below.
139	const attractsEnchantmentSurcharge = (item: Item): boolean =>
140	  (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_THRESHOLD;
141	
142	const surchargesFor = (item: Item): number => {
143	  const base = basePremiumOf(item);
144	  const curse = item.cursed ? percentOf(base, CURSE_PERCENT) : 0;
145	  const enchantment = attractsEnchantmentSurcharge(item)
146	    ? percentOf(base, HIGH_ENCHANTMENT_PERCENT)
147	    : 0;
148	
149	  return curse + enchantment;
150	};
151	
152	const itemSpecificModifiers = (mainItems: Item[]): number =>
153	  mainItems.reduce((sum, item) => sum + surchargesFor(item), 0);
154	
155	// Policy-wide modifiers are percentages of the whole policy's base premium,
156	// taken from the UNMODIFIED base so item-specific modifiers never feed into
157	// them - that is what keeps modifiers additive instead of compounding.
158	// Discounts are negative terms.
159	const qualifiesForLoyalty = (customer: Customer): boolean =>
160	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
161	
162	const policyWideModifiers = (
163	  basePremium: number,
164	  customer: Customer,
165	  isFollowUp: boolean,
166	): number => {
167	  // First insurance applies to every quote, including follow-ups: the spec
168	  // treats each item in a quote as a first insurance regardless of customer
169	  // history, so this coexists with the follow-up discount.
170	  const firstInsurance = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
171	  const loyalty = qualifiesForLoyalty(customer)
172	    ? discountOf(basePremium, LOYALTY_DISCOUNT_PERCENT)
173	    : 0;
174	  const followUp = isFollowUp
175	    ? discountOf(basePremium, FOLLOW_UP_DISCOUNT_PERCENT)
176	    : 0;
177	
178	  return firstInsurance + loyalty + followUp;
179	};
180	
181	// Amounts are rounded in the MHPCO's favor, and the direction depends on who
182	// pays. The two directions are defined together so the asymmetry is visible
183	// at a glance; they are deliberately two named functions rather than one
184	// round(amount, direction), because the name at each call site is what makes
185	// the direction self-evident. Every amount inside the pipelines stays an
186	// exact fraction - rounding is applied once per amount, as late as each
187	// pipeline allows.
188	//
189	// A premium is owed TO MHPCO, so it rounds up. Applied at the point a quote
190	// result is emitted (priceQuote).
191	const roundPremiumInMhpcoFavor = (premium: number): number =>
192	  Math.ceil(premium);
193	
194	// A payout is owed BY MHPCO, so it rounds down. Applied earlier than its
195	// premium counterpart - inside drawAgainstPolicy rather than at emission -
196	// because the rounded payout is what decrements the cap; rounding only at
197	// emission would leave remainingCap fractional.
198	const roundPayoutInMhpcoFavor = (payout: number): number => Math.floor(payout);
199	
200	// Returns the EXACT, unrounded premium. Rounding happens once, at the point
201	// the result is emitted - see runScenario.
202	const quotePremium = (
203	  step: QuoteStep,
204	  customer: Customer,
205	  isFollowUp: boolean,
206	): number => {
207	  const { mainItems, components } = partitionByComponent(step.items);
208	
209	  const basePremium =
210	    mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0) +
211	    componentsPremium(components);
212	
213	  const modifiers =
214	    itemSpecificModifiers(mainItems) +
215	    policyWideModifiers(basePremium, customer, isFollowUp);
216	
217	  return basePremium + modifiers + PROCESSING_FEE;
218	};
219	
220	const insuranceValueOf = (item: Item): number =>
221	  isComponent(item) ? COMPONENT_INSURANCE_VALUE : INSURANCE_VALUES[item.type];
222	
223	// The insurance sum is a plain per-item total: the component block discount
224	// affects the premium only, never the sum insured.
225	const insuranceSumOf = (items: Item[]): number =>
226	  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
227	
228	// A policy remembers what it covers and how much of its cap is left, so later
229	// claim steps can draw against it.
230	type Policy = {
231	  items: Item[];
232	  remainingCap: number;
233	};
234	
235	const openPolicy = (items: Item[]): Policy => ({
236	  items,
237	  remainingCap: CAP_MULTIPLE * insuranceSumOf(items),
238	});
239	
240	// Damage to a sufficiently enchanted item is only half reimbursed. Named for
241	// the consequence rather than the measurement, so it cannot be mistaken for
242	// the premium-side attractsEnchantmentSurcharge above.
243	const qualifiesForHalfReimbursement = (item: Item): boolean =>
244	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
245	
246	// Decides how much of a damage amount the clauses cover, before the
247	// deductible. Takes the amount rather than the whole Damage: the itemType has
248	// already been resolved to an item by the caller.
249	const reimbursementFor = (item: Item, amount: number): number =>
250	  qualifiesForHalfReimbursement(item)
251	    ? percentOf(amount, HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT)
252	    : amount;
253	
254	// Each damage entry carries its own deductible, applied after the
255	// reimbursement clauses have decided how much of the damage is covered.
256	const payoutForDamage = (policy: Policy, damage: Damage): number => {
257	  const damagedItem = policy.items.find(
258	    (item) => item.type === damage.itemType,
259	  );
260	
261	  // assertDamagesWithinCover has already established that every damage names
262	  // an insured item, so this is unreachable for a validated claim. Stated as a
263	  // check rather than an "as Item" cast: a cast would quietly hand undefined
264	  // to reimbursementFor if a caller ever settled a claim without validating
265	  // it first, which is the TypeError the coverage rule exists to prevent.
266	  if (!damagedItem) {
267	    throw new Error(`item not covered by policy: ${damage.itemType}`);
268	  }
269	
270	  return reimbursementFor(damagedItem, damage.amount) - DEDUCTIBLE_PER_DAMAGE;
271	};
272	
273	// Returns what the incident's damages come to BEFORE the cap is applied -
274	// hence "desired" rather than "settled": this amount is what the claimant has
275	// coming if the policy still has the cover, and drawAgainstPolicy decides
276	// whether it does.
277	const desiredPayoutFor = (policy: Policy, incident: Incident): number =>
278	  incident.damages.reduce(
279	    (total, damage) => total + payoutForDamage(policy, damage),
280	    0,
281	  );
282	
283	type QuoteResult = { premium: number };
284	type ClaimResult = { payout: number; remainingCap: number };
285	
286	// The cap limits the money actually paid out, not just the reported
287	// remainder: once it is exhausted the desired payout is cut down to whatever
288	// cover is left, and the remainder floors at 0. Takes the remaining cap
289	// itself rather than the whole Policy - that one number is the only thing
290	// this rule depends on.
291	const limitToRemainingCap = (desired: number, remainingCap: number): number =>
292	  Math.min(desired, remainingCap);
293	
294	// Draws the payout against the policy's cap, so the policy carries less cover
295	// into any later claim.
296	const drawAgainstPolicy = (policy: Policy, incident: Incident): ClaimResult => {
297	  // Rounded before the cap is applied and decremented, so the remaining cover
298	  // never becomes fractional. No active test distinguishes this order from
299	  // clamping first: remainingCap is always integral, so either order agrees.
300	  const desired = roundPayoutInMhpcoFavor(desiredPayoutFor(policy, incident));
301	  const payout = limitToRemainingCap(desired, policy.remainingCap);
302	
303	  policy.remainingCap -= payout;
304	
305	  return { payout, remainingCap: policy.remainingCap };
306	};
307	
308	// An item type MHPCO does not underwrite cannot be priced at all, so a quote
309	// naming one is rejected outright rather than silently producing NaN.
310	const isKnownItemType = (item: Item): boolean =>
311	  MAIN_ITEM_TYPES.includes(item.type) || isComponent(item);
312	
313	const assertQuotableItems = (items: Item[]): void => {
314	  const unknown = items.find((item) => !isKnownItemType(item));
315	
316	  if (unknown) {
317	    throw new Error(`unknown item type: ${unknown.type}`);
318	  }
319	};
320	
321	const countOfType = (types: string[], type: string): number =>
322	  types.filter((candidate) => candidate === type).length;
323	
324	// Each damaged item must be one the policy actually insures, so a type may be
325	// claimed no more often than it is covered. Counting subsumes mere coverage:
326	// an uninsured type is the count-zero case, one damage against nothing.
327	const assertDamagesWithinCover = (
328	  policy: Policy,
329	  incident: Incident,
330	): void => {
331	  const damagedTypes = incident.damages.map((damage) => damage.itemType);
332	  const insuredTypes = policy.items.map((item) => item.type);
333	
334	  const overclaimed = damagedTypes.find(
335	    (type) =>
336	      countOfType(damagedTypes, type) > countOfType(insuredTypes, type),
337	  );
338	
339	  // Tested against undefined rather than for truthiness: overclaimed is a
340	  // string, so a falsy-but-present "" type would slip past a bare truthiness
341	  // check. (assertQuotableItems above guards an OBJECT, where the two forms
342	  // coincide - the shapes look parallel but are not.)
343	  if (overclaimed !== undefined) {
344	    throw new Error(
